function SubRx([string]$old, [string]$new) {
  $pat = ($old -split "`n" | ForEach-Object { [regex]::Escape($_.TrimEnd("`r")) }) -join "\r?\n"
  $c = ([regex]::Matches($script:s, $pat)).Count
  if ($c -ne 1) { throw "regex matched $c times: $($old.Substring(0,[Math]::Min(70,$old.Length)))" }
  $new = $new.Replace("`r`n", "`n")
  $script:s = [regex]::Replace($script:s, $pat, { param($m) $new })
  $script:n++
}

# THE FOLEY BANK: RECORDED RELOAD, BANDAGE AND ARMOUR SOUNDS (co-op hunt, 2026-09-28; found and drafted by agents, each verified by a second).

SubRx @'
function blipMine(type,a,b,c,d,e){
'@ @'
// v25.20, HIS ORDERS 2026-10-12 (about 21:10): "add good reload noises" and "add sounds for bandaging, applying armor, etc". THE FOLEY
// BANK. Every sound in the game was made from oscillators and noise, which is right for a gunshot crack and wrong for a magazine, a
// bandage or a plate: a reload was one 0.25 s click for every gun, and a bandage, a medkit and a plate were the menu chirp. SFXBANK holds
// 23 short recordings, all CC0 (Kenney, and zer0_sol, SpringySpringo, BMacZero, OwlishMedia and AntumDeluge on OpenGameArt; the sources,
// cuts and licences are in tools/sounds/LICENCES.txt, and the itch zip carries it): magazine out and in, a slide rack, a rifle release and
// charging handle, a pistol seat, a shotgun shell and pump, a bolt latch, a heavy box clack, a bandage tear and wrap, a medkit zip and
// snap, an injector, a plate clack, a velcro strap, a pin click, a keycard beep, a heavy door, a rummage, a pickup and an equip. Each was
// cut, mixed to mono, resampled to 22050 Hz, trimmed and peak normalised, and kept as an 8-bit mu-law WAV (about 29 KB a second; 216 KB
// for the lot, inside the 450 KB budget; Chrome decodes these files as they are). They are decoded the first time one is played, by
// hand (mu-law and PCM need no wait, so the first reload already sounds; anything else goes to the browser decoder). foley() plays
// one: yours centred in your ears (SPLIT SPEAKERS puts the window on its seat side, player 1 left and player 2 right, as every sound),
// a thing in the world placed by earsOf with the v23.73 width and through-the-wall muffle, on the bus its kind of sound rides, with a
// touch of pitch spread from the cosmetic stream. The party hears yours where you stand. This build adds the bank and the player only;
// the reload, healing and armour builds call it. Cosmetic only: no seeded draw, nothing under G.sim, no game state.
var SFXBANK={
  magOut:{c:'gun',g:0.26,d:0.1197,w:''},
  magIn:{c:'gun',g:0.26,d:0.2259,w:''},
  slideRack:{c:'gun',g:0.22,d:0.3387,w:''},
  rifleMagOut:{c:'gun',g:0.26,d:0.1786,w:''},
  rifleCharge:{c:'gun',g:0.26,d:0.4527,w:''},
  pistolSeat:{c:'gun',g:0.24,d:0.1468,w:''},
  shellIn:{c:'gun',g:0.22,d:0.1395,w:''},
  pump:{c:'gun',g:0.22,d:0.4082,w:''},
  boltLatch:{c:'gun',g:0.24,d:0.179,w:''},
  lmgClack:{c:'gun',g:0.22,d:0.1648,w:''},
  bandageTear:{c:'foley',g:0.2,d:0.5546,w:''},
  bandageWrap:{c:'foley',g:0.16,d:0.2748,w:''},
  medkitZip:{c:'foley',g:0.16,d:0.8194,w:''},
  medkitSnap:{c:'foley',g:0.2,d:0.2152,w:''},
  injector:{c:'foley',g:0.18,d:0.2817,w:''},
  plateClack:{c:'foley',g:0.24,d:0.3902,w:''},
  strapRip:{c:'foley',g:0.2,d:0.5683,w:''},
  pinClick:{c:'foley',g:0.22,d:0.3831,w:''},
  keyBeep:{c:'foley',g:0.1,d:0.2898,w:''},
  doorHeavy:{c:'mach',g:0.24,d:0.5302,w:''},
  rummage:{c:'foley',g:0.18,d:0.1988,w:''},
  pickup:{c:'foley',g:0.18,d:0.2016,w:''},
  equip:{c:'foley',g:0.2,d:0.2345,w:''}
};
var SFXB={buf:{},ac:null,nb:0,n:{},at:{},last:'',fail:0};
// one bank clip, decoded by hand into a buffer of context a: 8-bit mu-law (format 7) or 8 or 16-bit PCM, mono; null for anything else
function sfxbWav(a,s){
  var u, n, i=12, id, sz, fmt=0, ch=0, sr=0, bits=0, dOff=-1, dLen=0, k, b, c, x, q, v;
  if(!a||!s) return null;
  u=atob(s); n=u.length;
  if(n<44||u.slice(0,4)!=='RIFF'||u.slice(8,12)!=='WAVE') return null;
  function u32(o){ return (u.charCodeAt(o)|(u.charCodeAt(o+1)<<8)|(u.charCodeAt(o+2)<<16)|(u.charCodeAt(o+3)<<24))>>>0; }
  function u16(o){ return u.charCodeAt(o)|(u.charCodeAt(o+1)<<8); }
  while(i+8<=n){
    id=u.slice(i,i+4); sz=u32(i+4);
    if(id==='fmt '){ fmt=u16(i+8); ch=u16(i+10); sr=u32(i+12); bits=u16(i+22); }
    else if(id==='data'){ dOff=i+8; dLen=Math.min(sz,n-dOff); break; }
    i+=8+sz+(sz&1);
  }
  if(dOff<0||ch!==1||!(sr>=3000&&sr<=192000)) return null;
  if((fmt===7||fmt===1)&&bits===8) k=dLen; else if(fmt===1&&bits===16) k=dLen>>1; else return null;
  if(k<16) return null;
  b=a.createBuffer(1,k,sr); c=b.getChannelData(0);
  for(i=0;i<k;i++){
    if(fmt===7){ x=(~u.charCodeAt(dOff+i))&0xFF; q=((((x&0x0F)<<3)+0x84)<<((x>>4)&7))-0x84; c[i]=((x&0x80)?-q:q)/32768; }
    else if(bits===16){ v=u16(dOff+2*i); c[i]=(v>=32768?v-65536:v)/32768; }
    else c[i]=(u.charCodeAt(dOff+i)-128)/128;
  }
  return b;
}
// the whole bank, once per audio context
function sfxbDecode(a){
  if(!a) return 0;
  if(SFXB.ac===a) return SFXB.nb;
  SFXB.ac=a; SFXB.buf={}; SFXB.nb=0;
  Object.keys(SFXBANK).forEach(function(k){
    var b=null, s, u, i, pr;
    try{ b=sfxbWav(a,SFXBANK[k].w); }catch(e){ b=null; }
    if(b&&b.duration){ SFXB.buf[k]=b; SFXB.nb++; return; }
    if(!a.decodeAudioData) return;
    try{
      s=atob(SFXBANK[k].w); u=new Uint8Array(s.length);
      for(i=0;i<s.length;i++) u[i]=s.charCodeAt(i);
      pr=a.decodeAudioData(u.buffer,function(x){ if(x&&x.duration&&SFXB.ac===a) SFXB.buf[k]=x; },function(){ SFXB.fail++; });
      if(pr&&pr.then) pr.then(function(x){ if(x&&x.duration&&SFXB.ac===a) SFXB.buf[k]=x; },function(){});
    }catch(e2){ SFXB.fail++; }
  });
  return SFXB.nb;
}
// foley(role,x,y,o): play the bank clip ROLE. With no x it is your own, centred in your ears; with x,y it sits in the world. o (all
// optional): g a gain on top of the bank level, rate a playback rate, vary the pitch spread (0.04), off and dur a trim window in seconds,
// at a delay (at most 1 s), cat another bus, gap the shortest time between two of the same (0.03 s), local to keep it from the party.
// Returns the BufferSource that plays, or false.
function foley(role,x,y,o){
  var K=SFXBANK[role], own, a, b, t, E, P=null, d=0, vol=1, pan=0, lk, out, at, rate, off, dur, gv, end, src, g, tl, pn, lp, p;
  o=o||{};
  if(!K||(G&&G.sim)) return false;
  own=(x===undefined||x===null);
  if(!own&&!(isFinite(x)&&isFinite(y))) return false;
  if(!o.local&&typeof NET==='object'&&NET&&NET.on&&!NET.fxIn&&G&&G.player){ p=G.player; netFxNoise('f:'+role,own?p.x:x,own?p.y:y); }   // the party hears it where it is
  if(typeof NET==='object'&&NET&&NET.specTick) return false;
  a=ac(); if(!a) return false;
  sfxbDecode(a);
  b=SFXB.buf[role]; if(!b||!b.duration) return false;
  if(!own){
    E=earsOf(x,y); d=E.d; P=sndPlace(x,y);
    vol=d<=450?1-d/900:Math.max(0,0.5*(900-d)/450); if(vol<=0.02) return false;   // the fade every world sound has (blip)
    pan=clamp(E.pan*(P.panK||1),-1,1);
  }
  t=a.currentTime; lk=(own?'m:':'w:')+role;
  if(SFXB.at[lk]!==undefined&&t>=SFXB.at[lk]&&t-SFXB.at[lk]<(o.gap===undefined?0.03:+o.gap)) return false;
  out=sndBus(o.cat||K.c||'foley'); if(!out) return false;
  SFXB.at[lk]=t;
  at=t+Math.min(1,Math.max(0,+o.at||0));
  rate=((o.rate>0)?+o.rate:1)*(1+fxn(-1,1)*(o.vary===undefined?0.04:Math.min(0.3,Math.max(0,+o.vary||0))));
  off=Math.max(0,Math.min(b.duration-0.01,+o.off||0));
  dur=(o.dur>0)?Math.min(+o.dur,b.duration-off):(b.duration-off);
  gv=K.g*(o.g===undefined?1:Math.max(0,+o.g||0))*vol;
  try{
    src=a.createBufferSource(); src.buffer=b; src.playbackRate.value=rate;
    g=a.createGain(); g.gain.setValueAtTime(gv,at);
    if(o.dur>0){ end=at+dur/rate; g.gain.setValueAtTime(gv,Math.max(at,end-0.015)); g.gain.linearRampToValueAtTime(0.0001,end); }   // a cut ends on a 15 ms fade, never a click
    src.connect(g); tl=g;
    if(!own&&PAN_OK&&a.createStereoPanner){ pn=a.createStereoPanner(); pn.pan.value=pan; tl.connect(pn); tl=pn; }
    if(!own&&P&&P.lp>0){ lp=a.createBiquadFilter(); lp.type='lowpass'; lp.frequency.value=P.lp; lp.Q.value=0.7; tl.connect(lp); tl=lp; }   // v23.73: through the wall
    tl.connect(out);
    src.start(at,off,dur);
  }catch(e){ return false; }
  SFXB.n[role]=(SFXB.n[role]||0)+1; SFXB.last=role;
  return src;
}
